using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json.Linq;
public static class B3Details {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/Review/2026-11-09_B3_FullFloor/";
 static void Shot(string n,Vector3 pos,Vector3 to,float fov=72){var go=new GameObject("TemporaryReviewCamera"){hideFlags=HideFlags.HideAndDontSave};var c=go.AddComponent<Camera>();c.transform.position=pos;c.transform.LookAt(to);c.fieldOfView=fov;c.nearClipPlane=.035f;c.farClipPlane=300;c.useOcclusionCulling=false;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1440,1000,24){antiAliasing=4};var old=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1440,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1440,1000),0,0);tex.Apply();File.WriteAllBytes(O+n+".png",tex.EncodeToPNG());}finally{RenderTexture.active=old;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||StaticOcclusionCulling.isRunning||!s.path.EndsWith("Level_B3_Circular.unity"))throw new Exception("Saved idle B3 required");var plan=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B3_FullFloor/layout.json"));var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>()).ToArray();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));player.SetActive(false);int count=0;try{
 foreach(var t in all.Where(t=>t.name=="WorkLighting")){foreach(var l in t.GetComponentsInChildren<Light>())l.enabled=true;var lamp=AssetDatabase.LoadAssetAtPath<Material>("Assets/Afrer_Seconds/05.Model/Environment/B3/Materials/B3M_Lamp.mat");foreach(var mr in t.GetComponentsInChildren<MeshRenderer>())mr.sharedMaterials=mr.sharedMaterials.Select(m=>m&&m.name=="BS_LampOff"?lamp:m).ToArray();}
 foreach(var r in plan["rooms"].Where(r=>(string)r["kind"]!="core")){var center=new Vector3((float)r["x"],-49,-(float)r["v"]);var d=r["doors"][0];var dir=new Vector3((float)d["x"],0,(float)d["z"]).normalized;Shot("reviewlit_"+(string)r["id"],center+dir*((float)r["r"]-1.3f)+Vector3.up*1.65f,center+Vector3.up*1.0f,90);count++;}
 foreach(string model in new[]{"BS_SampleRack_1","BS_DeepFreezer","BS_AccessionBench","BS_PackingBench","BS_ServerRack_1","BS_FilterBank","B3_CryogenicDewar","B3_SealedSampleCarrier","BS_SealedWasteStation","LB_SignalAnalysisBench"}){var p=plan["placements"].First(q=>(string)q["model"]==model);var t=all.Single(t=>t.name==(string)p["name"]);float height=(float)p["size"][1],depth=(float)p["size"][2];var pos=t.TransformPoint(new Vector3(.2f,model.Contains("Carrier")?.65f:1.65f,depth*.5f+Mathf.Max(.7f,(float)p["size"][0]*.50f)));var target=t.TransformPoint(new Vector3(0,Mathf.Min(1.25f,height*.60f),.1f));Shot("detail_"+model,pos,target,70);count++;}
 var mt=all.Single(t=>t.name=="B3_N01_CCTVWallMount");Shot("detail_CCTV_mount",mt.TransformPoint(new Vector3(1.15f,3.1f,1.8f)),mt.TransformPoint(new Vector3(0,3.2f,.25f)),65);count++;
 }finally{EditorSceneManager.OpenScene(s.path);}return new{images=count,mode="Temporary work-light preview only; saved default circuit state restored"};}
}
